import { LogicWrapper, MakeLogicType, afterMount, kea, key, path, props, propsChanged } from 'kea'
import { loaders } from 'kea-loaders'

import type { DataTableNode } from '~/queries/schema/schema-general'

import { createAccountSqlQueryNode } from './accountSqlQuery'

export interface AccountSqlQueryLogicProps {
    accountId: string
    externalId: string
    instanceId?: string
    query: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountSqlQueryLogicValues {
    queryNode: DataTableNode | null
    queryNodeLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountSqlQueryLogicActions {
    loadQueryNode: (_: void) => void
    loadQueryNodeFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadQueryNodeSuccess: (
        queryNode: DataTableNode | null,
        payload?: void
    ) => {
        queryNode: DataTableNode | null
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountSqlQueryLogicMeta {
    key: string
}

export type accountSqlQueryLogicType = MakeLogicType<
    accountSqlQueryLogicValues,
    accountSqlQueryLogicActions,
    AccountSqlQueryLogicProps,
    accountSqlQueryLogicMeta
>

export const accountSqlQueryLogic: LogicWrapper<accountSqlQueryLogicType> = kea<accountSqlQueryLogicType>([
    props({} as AccountSqlQueryLogicProps),
    key(({ accountId, externalId, instanceId }) => `${accountId}:${externalId}:${instanceId ?? 'default'}`),
    path((key) => ['products', 'customer_analytics', 'components', 'Accounts', 'accountSqlQueryLogic', key]),
    loaders(({ props }) => ({
        queryNode: [
            null as DataTableNode | null,
            {
                loadQueryNode: async (_: void, breakpoint) => {
                    const node = await createAccountSqlQueryNode(props.query, props.externalId)
                    breakpoint()
                    return node
                },
            },
        ],
    })),
    afterMount(({ actions }) => actions.loadQueryNode()),
    propsChanged(({ actions, props }, oldProps) => {
        if (props.query !== oldProps.query) {
            actions.loadQueryNode()
        }
    }),
])
